SELECT n.id, n.user_id, u.name AS user_name, n.title, n.content, n.type, n.related_id, n.related_type, n.is_read, n.create_time, n.read_time FROM system_notice n LEFT JOIN user_info u ON n.user_id = u.id WHERE n.is_deleted = 0
AND n.type = #{type}
AND n.user_id = #{userId}
AND n.is_read = #{isRead}
AND (n.title LIKE CONCAT('%', #{keyword}, '%') OR n.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY n.create_time DESC LIMIT #{offset}, #{pageSize}

